import argparse
import datetime
import hashlib
from pathlib import Path

from wlc_cmn.utf8_io import force_utf8_io
from mb_cmn import paths
from mb_cmn import vendoring_sync

_DEST_REPO = paths.repo_root()
_UXLC_SOURCE_REPO = paths.uxlc_utils_dir()
_SOURCE_UXLC39 = _UXLC_SOURCE_REPO / "in" / "UXLC-39"
_DEST_UXLC39 = paths.in_dir() / "UXLC-39"
_SOURCE_UXLCMISC = _UXLC_SOURCE_REPO / "out" / "UXLC-misc"
_DEST_UXLCMISC = paths.in_dir() / "UXLC-misc"


def almost_main(argv: list[str] | None = None) -> None:
    """The body, callable in-process -- ``main_0_mega.py`` runs it as a step."""
    args = _parse_args(argv)

    # The sibling ROOT is checked through mb_cmn.paths, whose message names both env
    # overrides: an absent root means the clone is misplaced -- or, far likelier, that
    # this checkout is a git worktree nested under .claude/worktrees/ and so has no
    # siblings at all -- and that is fixable advice.  The root's own SUBTREES stay on
    # the bare _require_dir deliberately: with the root confirmed present, the clone is
    # already where this program expects it, so a missing subtree means a wrong or
    # stale version of the sibling, and pointing the reader at REPOS_ROOT would send
    # them to relocate a clone that is not the problem.  That reasoning holds only if
    # the root is checked BEFORE its subtrees, so the order below is load-bearing.
    paths.require_uxlc_utils_dir()
    _require_dir(_SOURCE_UXLC39)
    _require_dir(_DEST_UXLC39)
    _require_dir(_SOURCE_UXLCMISC)
    _require_dir(_DEST_UXLCMISC)

    synced_uxlc39, changed_uxlc39 = _sync(_SOURCE_UXLC39, _DEST_UXLC39, (".xml",))
    synced_uxlcmisc, changed_uxlcmisc = _sync(
        _SOURCE_UXLCMISC, _DEST_UXLCMISC, (".json",)
    )

    uxlc_commit, uxlc_tag = vendoring_sync.get_git_info(_UXLC_SOURCE_REPO)
    date_str = datetime.date.today().isoformat()
    wrote_uxlc39 = _maybe_write_provenance(
        _DEST_UXLC39,
        source_rel="UXLC-utils/in/UXLC-39",
        copied_files=synced_uxlc39,
        commit=uxlc_commit,
        tag=uxlc_tag,
        date_str=date_str,
        changed=changed_uxlc39,
        force=args.force_provenance,
    )
    wrote_uxlcmisc = _maybe_write_provenance(
        _DEST_UXLCMISC,
        source_rel="UXLC-utils/out/UXLC-misc",
        copied_files=synced_uxlcmisc,
        commit=uxlc_commit,
        tag=uxlc_tag,
        date_str=date_str,
        changed=changed_uxlcmisc,
        force=args.force_provenance,
    )

